def _paths_from_patch(patch: str) -> tuple:
    """The source files a unified-diff gold patch touches (its `+++ b/<path>` headers),
    used as the `relevant_paths` localization hint so multi-instance eval doesn't depend on
    hand-curating paths per instance (real file localization stays out of scope, as noted
    for the pylint spike)."""
    paths = []
    for line in patch.splitlines():
        if line.startswith("+++ b/"):
            p = line[len("+++ b/"):].strip()
            if p and p != "/dev/null" and p not in paths:
                paths.append(p)
    return tuple(paths)


