def make_client(*, timeout: float = 120.0, max_retries: int = 1):
    """The single OpenAI-SDK client factory used by every runner (solo/kernel/delm), so
    they all talk to the same endpoint. When LITELLM_BASE_URL + LITELLM_AUTH_TOKEN are set
    (an OpenAI-compatible proxy -- e.g. the internal LiteLLM gateway), route through it;
    otherwise fall back to the default OpenAI endpoint + OPENAI_API_KEY. Routing is chosen
    here, once, so no runner hard-codes an endpoint."""
    from openai import OpenAI

    base_url = os.environ.get("LITELLM_BASE_URL")
    token = os.environ.get("LITELLM_AUTH_TOKEN")
    if base_url and token:
        base = base_url.rstrip("/")
        if not base.endswith("/v1"):
            base += "/v1"
        return OpenAI(base_url=base, api_key=token, timeout=timeout, max_retries=max_retries)
    return OpenAI(timeout=timeout, max_retries=max_retries)

