def commute_class(art, variant_effects, neighbour_effects) -> tuple:
    """The commute-class signature of one variant against a fixed neighbour: the sorted set of
    `(tag, path)` cells on which the variant genuinely FAILS to commute with the neighbour under
    the cell law's own conflict predicate (`eico.cells._conflicts`). Empty = the variant commutes
    cleanly. The signature keys on WHERE the interaction is, not the variant's specific written
    value, so surface-only variants (renamed locals writing the same cell, blind writes of the
    same value) collapse to one class while genuinely-different interaction structure splits —
    exactly the commute-class equivalence the entropy is meant to measure."""
    sig: set[tuple] = set()
    for ev in variant_effects:
        wv, rv = write_cells(art, ev), read_cells(art, ev)
        for en in neighbour_effects:
            wn, rn = write_cells(art, en), read_cells(art, en)
            for w in wv:
                for o in (rn | wn):
                    if _conflicts(w, o):
                        sig.add((w.tag, w.path))
            for w in wn:
                for o in (rv | wv):
                    if _conflicts(w, o):
                        sig.add((w.tag, w.path))
    return tuple(sorted(sig))

