def failing_test_summary(output: str, max_lines: int = 40) -> str:
    """Extract the actionable tail of a red pytest run so a coder can iterate toward
    green (WS1.2). The raw `PromotionResult.test_output` is the whole pytest stream;
    a coder does not need the collection preamble, only (a) the `FAILURES` section
    with the assertion tracebacks and (b) the `short test summary info` FAILED lines.
    Prefer the `=== FAILURES ===` section onward (that is where the traceback and the
    summary both live); fall back to the last `max_lines` lines when pytest emitted no
    such banner (a smoke/import failure, a collection error). Always bounded so it
    cannot blow up a coder's context window."""
    if not output:
        return ""
    lines = output.splitlines()
    start = None
    for i, line in enumerate(lines):
        if "=== FAILURES ===" in line or line.strip().startswith("=") and "FAILURES" in line:
            start = i
            break
    tail = lines[start:] if start is not None else lines
    if len(tail) > max_lines:
        # keep the head of the FAILURES section (the first traceback) AND the very
        # end (the short summary of which tests failed) — the middle is the least
        # actionable part when many tests fail.
        head = tail[: max_lines - 12]
        foot = tail[-12:]
        tail = head + ["... (test output truncated) ..."] + foot
    return "\n".join(tail).strip()


